package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertDoesNotThrow;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.IOException;
import java.io.OutputStream;
import java.net.URI;
import java.nio.charset.StandardCharsets;
import java.nio.file.AccessMode;
import java.nio.file.FileSystem;
import java.nio.file.Files;
import java.nio.file.NoSuchFileException;
import java.nio.file.Path;
import java.util.Map;

import org.apache.commons.compress.archivers.tar.TarArchiveEntry;
import org.apache.commons.compress.archivers.tar.TarArchiveOutputStream;
import org.junit.jupiter.api.Test;

final class TarFileSystemProviderMutaGate3Test {
  @Test
  void pathExistence_distinguishesExistingAndMissingEntries() throws IOException {
    Path tarPath = Files.createTempFile("tarballfs-mutagate3-", ".tar");
    try {
      byte[] data = "inner".getBytes(StandardCharsets.UTF_8);
      try (OutputStream out = Files.newOutputStream(tarPath);
          TarArchiveOutputStream tarOut = new TarArchiveOutputStream(out)) {
        TarArchiveEntry entry = new TarArchiveEntry("dir/inner.txt");
        entry.setSize(data.length);
        tarOut.putArchiveEntry(entry);
        tarOut.write(data);
        tarOut.closeArchiveEntry();
      }

      TarFileSystemProvider provider = new TarFileSystemProvider();
      URI uri = URI.create("tar:" + tarPath.toAbsolutePath());
      try (FileSystem fs = provider.newFileSystem(uri, Map.of())) {
        // Exact entry and implied directory exist.
        assertDoesNotThrow(() -> provider.checkAccess(fs.getPath("/dir/inner.txt"), AccessMode.READ));
        assertDoesNotThrow(() -> provider.checkAccess(fs.getPath("/dir"), AccessMode.READ));
        assertTrue(Files.exists(fs.getPath("/dir/inner.txt")));
        assertTrue(Files.exists(fs.getPath("/dir")));

        // Missing entries must be reported as missing.
        assertThrows(NoSuchFileException.class,
            () -> provider.checkAccess(fs.getPath("/nope.txt"), AccessMode.READ));
        assertThrows(NoSuchFileException.class,
            () -> provider.checkAccess(fs.getPath("/dir/missing.txt"), AccessMode.READ));
        assertThrows(NoSuchFileException.class,
            () -> provider.checkAccess(fs.getPath("/di"), AccessMode.READ));
        assertFalse(Files.exists(fs.getPath("/nope.txt")));
        assertFalse(Files.exists(fs.getPath("/dir/missing.txt")));
        assertThrows(NoSuchFileException.class,
            () -> Files.readAttributes(fs.getPath("/nope.txt"),
                java.nio.file.attribute.BasicFileAttributes.class));
      }
    } finally {
      Files.deleteIfExists(tarPath);
    }
  }
}

