package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.IOException;
import java.io.OutputStream;
import java.net.URI;
import java.nio.charset.StandardCharsets;
import java.nio.file.FileSystem;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Map;

import org.apache.commons.compress.archivers.tar.TarArchiveEntry;
import org.apache.commons.compress.archivers.tar.TarArchiveOutputStream;
import org.junit.jupiter.api.Test;

final class TarFileSystemProviderMutaGate25Test {
  @Test
  void pathExistsInTar_distinguishesImpliedDirectoriesFromMissingPaths() throws IOException {
    Path tarPath = Files.createTempFile("tarballfs-mutagate-", ".tar");
    try {
      try (OutputStream out = Files.newOutputStream(tarPath);
          TarArchiveOutputStream tarOut = new TarArchiveOutputStream(out)) {
        addEntry(tarOut, "root.txt", "root");
        addEntry(tarOut, "dir/inner.txt", "inner");
        addEntry(tarOut, "dir/sub/leaf.txt", "leaf");
      }

      TarFileSystemProvider provider = new TarFileSystemProvider();
      URI uri = URI.create("tar:" + tarPath.toAbsolutePath());
      try (FileSystem fs = provider.newFileSystem(uri, Map.of())) {
        TarFileSystem tfs = (TarFileSystem) fs;

        // Existing: root, exact entries, implied directories.
        assertTrue(TarFileSystemProvider.pathExistsInTar(tfs, ""));
        assertTrue(TarFileSystemProvider.pathExistsInTar(tfs, "root.txt"));
        assertTrue(TarFileSystemProvider.pathExistsInTar(tfs, "dir/inner.txt"));
        assertTrue(TarFileSystemProvider.pathExistsInTar(tfs, "dir"));
        assertTrue(TarFileSystemProvider.pathExistsInTar(tfs, "dir/sub"));

        // Missing: must be false.
        assertFalse(TarFileSystemProvider.pathExistsInTar(tfs, "nope"));
        assertFalse(TarFileSystemProvider.pathExistsInTar(tfs, "di"));
        assertFalse(TarFileSystemProvider.pathExistsInTar(tfs, "dir/missing"));
        assertFalse(TarFileSystemProvider.pathExistsInTar(tfs, "dir/sub/leaf.txt/x"));
        assertFalse(TarFileSystemProvider.pathExistsInTar(tfs, "root.txt/child"));
      }
    } finally {
      Files.deleteIfExists(tarPath);
    }
  }

  private static void addEntry(TarArchiveOutputStream tarOut, String name, String content)
      throws IOException {
    byte[] data = content.getBytes(StandardCharsets.UTF_8);
    TarArchiveEntry entry = new TarArchiveEntry(name);
    entry.setSize(data.length);
    tarOut.putArchiveEntry(entry);
    tarOut.write(data);
    tarOut.closeArchiveEntry();
  }
}
